-- 98_PUBLISH_HIDDEN_ATHLETES_2026.sql
-- Approved by Zachary, 2026-11-13. Data change, not schema.
--
-- 950 athlete profiles were created by the 2026 results imports (Aug 5 and
-- Sep 29) and never published, although their results are public. Checked
-- against every public profile (name, near spellings at the same school,
-- class, gender):
--   * 947 are published: the 946 with no duplicate, plus Ava Bussert
--     (Northwestern, 2030): same grade as Annabelle Bussert but different
--     races (one shared meet with different times), so two athletes.
--   * 3 are merged into the existing public profile (same school and
--     graduation year): see section 2.
-- Each update only touches a profile that is still hidden, unmerged,
-- unarchived and not suspended, and each merge is skipped when it is
-- already done, so running this twice changes nothing more.
-- Run once, 2026-11-13 10:50 AM ET (947 published, 3 merged).
--
-- Undo:
--   section 1: update public.athlete_profiles set public_visible = false,
--     published_at = null where id in (<the ids below>);
--   section 2: select public.athlete_unmerge_profiles_v1(<merge id>,
--     'Podium Watch Admin'); for each merge (merge ids are in the
--     athlete merge log, newest first).

begin;

-- 1. Publish
